using Ordering;
// Deterministic in-memory test helpers
public sealed class RecordingShipper : IShipper
{
    private readonly string _label;

    public RecordingShipper(string label)
    {
        _label = label;
    }

    public string Name => "RecordingShipper";
    public List<string> References { get; } = new();
    public List<string> Services { get; } = new();

    public string CreateLabel(string reference, string service)
    {
        References.Add(reference);
        Services.Add(service);
        return _label;
    }
}

// H1 [happy_path]: Valid standard GB order follows ordinary processing path
{
    var shipper = new RecordingShipper("LBL-REF-100-standard");
    var processor = new OrderProcessor(shipper);
    var customer = new Customer
    {
        Tier = CustomerTier.Standard,
        Address = new Address
        {
            CountryCode = "GB",
            City = "London",
            PostalCode = "SW1A1AA"
        }
    };
    var order = new Order
    {
        Reference = "REF-100",
        Channel = OrderChannel.Web,
        DiscountOverride = null,
        Lines = new List<OrderLine>
        {
            new OrderLine { Sku = "SKU-A", Quantity = 2, UnitPrice = 50.00m }
        }
    };
    
    Check.SequenceEqual(new string[0], processor.ValidateOrder(order, customer));
    Check.True(processor.MeetsMinimum(order));
    Check.True(processor.CheckAddress(customer.Address));
    Check.Equal(20.00m, processor.ComputeTax(order, customer));
    Check.Equal(0.00m, processor.EstimateDuty(order, customer));
    Check.SequenceEqual(new[] { "PARCEL SKU-A" }, processor.BuildManifest(order));
    Check.Equal("small", processor.Classify(order, customer));
    Check.Equal(0.00m, processor.ApplyDiscount(order, customer));
    Check.Equal("standard", processor.SelectService(customer));
    Check.Equal("LBL-REF-100-standard", processor.Dispatch(order, customer));
    Check.Equal(1, processor.DispatchedCount);
}

